                                                .foregroundColor(.gray.opacity(0.7))

                                        }
                                        .font(.body)
                                        .foregroundColor(.primary)
                                        .padding(.horizontal)
                                        .padding(.vertical, 4)
                                    }


                                    Divider().padding(.leading)
                                }
                            }
                        }

                        VStack(alignment: .leading) {
                            Text("discover.support")
                                .font(.title2).bold()
                                .padding(.top, 16)
                                .padding(.bottom, 8)
                                .padding(.horizontal)

                            VStack(alignment: .leading) {
                                Divider()

                                Button(action: {
                                    let appID = "1506614493"
                                    let urlStr = "https://itunes.apple.com/app/id\(appID)?action=write-review"
                                    guard let url = URL(string: urlStr) else { return }
                                    openURL(url)
                                }, label: {
                                    HStack {
                                        Image(systemName: "star")
                                        Text("discover.rate")
                                        Spacer()
                                    }
                                    .font(.body)
                                    .foregroundColor(.primary)
                                })

                                Divider()

                                Button(action: {
                                    openURL(contributeURL)
                                }, label: {
                                    HStack {
                                        Image(systemName: "plus.app")
                                        Text("discover.contribute")
                                        Spacer()
                                    }
                                    .font(.body)
                                    .foregroundColor(.primary)
                                })

                                Divider()

                                NavigationLink(value: DiscoverRoute.acknowledgements) {
                                    HStack {
                                        Image(systemName: "info.circle")
                                        Text("discover.acknowledgements")
                                        Spacer()
                                    }
                                    .font(.body)
                                    .foregroundColor(.primary)
                                }

                                Divider()
                            }
                            .frame(minWidth: 0, maxWidth: .infinity, minHeight: 0, maxHeight: .infinity, alignment: .topLeading)
                            .padding(.horizontal)
                            .padding(.bottom)
                        }

#if DEVELOPMENT
                        VStack(alignment: .leading) {
                            Text("Dev")
                                .font(.title2).bold()
                                .padding(.top, 16)
                                .padding(.bottom, 8)
                                .padding(.horizontal)

                            VStack(alignment: .leading) {
                                Divider()

                                NavigationLink(value: DiscoverRoute.settings) {
